out = {}
for en, v in T.items():
    out[en] = None if v is None else {"fr-fr": v[0], "it-it": v[1], "es-es": v[2]}
here = os.path.dirname(os.path.abspath(__file__))
json.dump(out, open(os.path.join(here, "translations.json"), "w"), ensure_ascii=False, indent=1)
strings = json.load(open(os.path.join(here, "strings.json")))
missing = [s for s in strings if s not in out]
print(f"{sum(v is not None for v in out.values())} translated, {sum(v is None for v in out.values())} kept in English, {len(missing)} not covered")
for s in missing: print("  MISSING:", repr(s))
